import sys

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', nodes: 'List[TreeNode]') -> 'TreeNode':
        sys.setrecursionlimit(20000)
        targets = set(nodes)
        k = len(targets)
        self.ans = None

        def dfs(node):
            if not node:
                return 0
            total = dfs(node.left) + dfs(node.right) + (node in targets)
            if total == k and self.ans is None:
                self.ans = node
            return total

        dfs(root)
        return self.ans

