class Solution {
public:
    unordered_set<int> targets;
    TreeNode* ans = nullptr;

    int dfs(TreeNode* node) {
        if (!node) return 0;
        int total = dfs(node->left) + dfs(node->right)
                  + (targets.count(node->val) ? 1 : 0);
        if (total == (int)targets.size() && !ans) ans = node;
        return total;
    }

    TreeNode* lowestCommonAncestor(TreeNode* root, vector<TreeNode*>& nodes) {
        for (TreeNode* n : nodes) targets.insert(n->val);
        dfs(root);
        return ans;
    }
};

