class Solution {
    private Set<TreeNode> targets = new HashSet<>();
    private TreeNode ans = null;
    private int k;

    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode[] nodes) {
        targets.addAll(Arrays.asList(nodes));
        k = nodes.length;
        dfs(root);
        return ans;
    }

    private int dfs(TreeNode node) {
        if (node == null) return 0;
        int total = dfs(node.left) + dfs(node.right) + (targets.contains(node) ? 1 : 0);
        if (total == k && ans == null) ans = node;
        return total;
    }
}

